routes.accessibility=[...routes.accessibility,...DATA.filter(x=>x.regional_role==='aging_agency').map(x=>x.program_id)];
const seniorTopics={"daily": ["fl-adrc", "fl-aging-directory", "fl-caregiver", "fl-cil-nwf", "fl-cil-drc", "fl-cil-ability1st", "fl-cil-jacksonville", "fl-cil-ncf", "fl-cil-dsil", "fl-cil-central", "fl-cil-rcds", "fl-cil-dac", "fl-cil-selfreliance", "fl-cil-suncoast", "fl-cil-gulfcoast", "fl-cil-southflorida", "fl-cil-keys", "fl-cil-cilo", "fl-cil-broward"], "accessibility": ["fl-at", "fl-waiver", "fl-adrc", "fl-cil-nwf", "fl-cil-drc", "fl-cil-ability1st", "fl-cil-jacksonville", "fl-cil-ncf", "fl-cil-dsil", "fl-cil-central", "fl-cil-rcds", "fl-cil-dac", "fl-cil-selfreliance", "fl-cil-suncoast", "fl-cil-gulfcoast", "fl-cil-southflorida", "fl-cil-keys", "fl-cil-cilo", "fl-cil-broward"], "vision": ["fl-blind", "fl-at"], "hearing": ["fl-relay", "fl-at"], "memory": ["alz-dementia-support", "fl-caregiver", "fl-adrc"], "costs": ["fl-ship", "fl-waiver", "fl-adrc"], "rights": ["fl-ombudsman", "fl-rights"]};
const ohioLiving=DATA.filter(x=>x.resource_role==='independent_living').map(x=>x.program_id),ohioCaregivers=DATA.filter(x=>x.resource_role==='caregiver_support').map(x=>x.program_id);
const ohioCenters=DATA.filter(x=>x.resource_role==='senior_center').map(x=>x.program_id);
const ohioHome=DATA.filter(x=>x.resource_role==='home_support').map(x=>x.program_id);
seniorTopics.daily.push(...ohioCenters);routes.local.push(...ohioCenters);
seniorTopics.daily.push(...ohioHome);routes.local.push(...ohioHome);routes.care.push(...ohioHome);
seniorTopics.daily.push(...ohioLiving,...ohioCaregivers);seniorTopics.accessibility.push(...ohioLiving);routes.accessibility.push(...ohioLiving);routes.local.push(...ohioLiving,...ohioCaregivers);routes.care.push(...ohioCaregivers,...ohioLiving);
routes.seniors=[...new Set(Object.values(seniorTopics).flat()),...DATA.filter(x=>x.regional_role).map(x=>x.program_id),'cms-care-compare'];
routes.community=DATA.filter(x=>['community_locator','senior_center'].includes(x.resource_role)).map(x=>x.program_id);
const routeNames={seniors:'Seniors and disability support',community:'Local posts and community connections',accessibility:'Ramps and home accessibility',priority:'Useful starting points',all:'All resources',benefits:'Help paying for care',survivors:'Surviving spouse support',care:'VA care and caregivers',rights:'Care concerns and rights',local:'Home and community support',housing:'Housing and service records'};
